+
+constexpr access_rights operator|=(const access_rights lhs, const access_rights rhs) noexcept
+{
+    return operator|(lhs, rhs);
+}
+
+constexpr access_rights operator&=(const access_rights lhs, const access_rights rhs) noexcept
+{
+    return operator&(lhs, rhs);
+}
+
+constexpr access_rights operator^=(const access_rights lhs, const access_rights rhs) noexcept
+{
+    return operator^(lhs, rhs);
