+// object representation
+template <typename T, uint64_t X>
+span<const uint8_t, (X == dynamic_extent ? dynamic_extent : sizeof(T) * X)> as_bytes(span<T, X> s) noexcept
+{
+    return {reinterpret_cast<const uint8_t*>(s.data()), s.size_bytes()};
