+#ifndef IOX_HOOFS_CXX_SPAN_ITERATOR_HPP
+#define IOX_HOOFS_CXX_SPAN_ITERATOR_HPP
+
+#include <iterator> // for reverse_iterator, distance, random_access_...
+
+#include "iceoryx_hoofs/cxx/requires.hpp"
+
+namespace iox
+{
+namespace cxx
