+        m_isValid = false;
+    }
+    else
+    {
+        m_msg.append(newEntry.str() + m_separator);
+        ++m_numberOfElements;
+    }
+}
+
+template <typename T>
+MqMessage& MqMessage::operator<<(const T& entry) noexcept
+{
+    addEntry(entry);
+    return *this;
+}
