+void SenderPort::freeChunk(mepoo::ChunkInfo* const chunkInfo)
+{
+    if (!deleteFromAllocatedChunkContainer(chunkInfo))
+    {
+        assert(false && "Application provided invalid chunk pointer to free");
+    }
+}
