+        MqMessage obsoleteMsg;
+        for (int i = 0; i < 4; ++i)
+        {
+            obsoleteMsg << msg.getElementAtIndex(i);
+        }
+        // set an invalid timestamp
+        obsoleteMsg << 0;
+        sendRegAck(obsoleteMsg);
+        sendRegAck(msg);
+    });
