+    static int copyCTor;
+    static int moveCTor;
+    static int moveAssignment;
+    static int copyAssignment;
+    static int dTor;
+    static int classValue;
+
+    class CTorTest
+    {
+      public:
+        CTorTest()
+        {
+            cTor++;
+            classValue = m_value;
+        }
+
+        CTorTest(const int value)
+            : m_value(value)
+        {
+            customCTor++;
+            classValue = m_value;
+        }
+
+        CTorTest(const CTorTest& rhs)
+        {
+            copyCTor++;
+            m_value = rhs.m_value;
+            classValue = m_value;
+        }
+
+        CTorTest(CTorTest&& rhs)
+        {
+            moveCTor++;
+            m_value = rhs.m_value;
+            classValue = m_value;
+        }
+
+        CTorTest& operator=(const CTorTest& rhs)
+        {
+            copyAssignment++;
+            m_value = rhs.m_value;
+            classValue = m_value;
+            return *this;
+        }
+
+        CTorTest& operator=(CTorTest&& rhs)
+        {
+            moveAssignment++;
+            m_value = rhs.m_value;
+            classValue = m_value;
+            return *this;
+        }
+
+        bool operator==(const CTorTest& rhs) const
+        {
+            return rhs.m_value == m_value;
+        }
+
+        ~CTorTest()
+        {
+            dTor++;
+            classValue = m_value;
+        }
+
+        int m_value = C_TOR_TEST_VALUE_DEFAULT_VALUE;
+    };
+
+
+    void SetUp()
+    {
+        cTor = 0;
+        customCTor = 0;
+        copyCTor = 0;
+        moveCTor = 0;
+        moveAssignment = 0;
+        copyAssignment = 0;
+        dTor = 0;
+        classValue = 0;
+    }
+
+    bool isSetupState()
+    {
+        if (cTor == 0 && customCTor == 0 && copyCTor == 0 && moveCTor == 0 && moveAssignment == 0 && copyAssignment == 0
